"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(inventoryMap, transactions):
    for t in transactions:
        if (t.type == 'purchase'):
            inventoryMap[t.item] = (inventoryMap[t.item] + t.qty)
        if (t.type == 'delivery'):
            inventoryMap[t.item] = (inventoryMap[t.item] - t.qty)
        if (inventoryMap[t.item] < 0):
            raise Exception('Insufficient Stock')
    return inventoryMap


class Transaction:
    def __init__(self, t_type, item, qty):
        self.type = t_type
        self.item = item
        self.qty = qty


# Example inventory
inventory = {
    "Apples": 10,
    "Bananas": 5,
    "Oranges": 8
}

# Example transactions
transactions = [
    Transaction("purchase", "Apples", 3),   # Apples → 13
    Transaction("delivery", "Bananas", 2),  # Bananas → 3
]

try:
    updated = unnamed_function(inventory, transactions)
    print(updated)
except Exception as e:
    print("ERROR:", e)

# Example transactions
transactions = [
    Transaction("delivery", "Oranges", 10)  # Oranges → -2 → ERROR
]

try:
    updated = unnamed_function(inventory, transactions)
    print(updated)
except Exception as e:
    print("ERROR:", e)